#pragma config(Sensor, S1,     touchSensor,    sensorEV3_Touch)
#pragma config(Sensor, S2,     sonarSensor,    sensorEV3_Ultrasonic)
#pragma config(Sensor, S3,     colorSensor,    sensorEV3_Color, modeEV3Color_Color)
#pragma config(Motor,  motorA,          leftMotor,     tmotorEV3_Large, PIDControl, encoder)
#pragma config(Motor,  motorB,          armMotor,      tmotorEV3_Medium, PIDControl, encoder)
#pragma config(Motor,  motorD,          rightMotor,    tmotorEV3_Large, PIDControl, encoder)
//*!!Code automatically generated by 'ROBOTC' configuration wizard               !!*//

/*
 * SFU MSE 110 - Autonomous Sumo Robot (Group 17)
 * Archived ROBOTC source; student numbers removed for public sharing.
 * Original group project.
 */

long r=0;
long g=0;
long b=0;

void setMotors(long lSpeed, long rSpeed, long armSpeed) {			//Set Motor Speed
	setMotorSpeed(leftMotor, lSpeed);
	setMotorSpeed(rightMotor, rSpeed);
	setMotorSpeed(armMotor, armSpeed);
}
void resetEncoders() {																				//Reset Motor Encoders
	resetMotorEncoder(leftMotor);
	resetMotorEncoder(rightMotor);
	resetMotorEncoder(armMotor);
}
bool robotFound() {																						//Detect Enemy using Ultrasonic Sensor
	return getUSDistance(sonarSensor) < 40;
}
bool edgeFoundRGB() {
	getColorRGB(colorSensor, r, g, b);
	return (r >= 38 && g >= 38 && b >= 25);
}
void scanTilt() {																							//Rotate after detecting White Line
	resetEncoders();
	setMotors(75,-75,0);
	while(getMotorEncoder(leftMotor) < 2000 && !robotFound()) {}// Rotate approx 120deg or until opp. is found
	setMotors(0,0,0);
}
void retract(bool shouldRetract) {														// Retract the 3rd Wheel if not being used.
	if(shouldRetract) {
		resetEncoders();
		setMotorTarget(armMotor, 150,-50);
		waitUntilMotorStop(armMotor);
	}
}
void backup() { 																							// Backup (used after detecting white line)
	setMotors(0,0,0);
	retract(true);
	resetEncoders();
	setMotors(-100, -100,0);
	while(getMotorEncoder(leftMotor) > -550) {}
	setMotors(0,0,0);																						//setMotorSpeed(armMotor, 0);
}

task main()
{
	//1. wait until button is pressed
	while(getTouchValue(touchSensor) != 1) {}

	//2. starting sequence
	getColorRGB(colorSensor, r, g, b);
	resetEncoders();
	setMotors(70,70,0);																					//go straight until reaching line
	while(!edgeFoundRGB()) {}																		//detect line
	backup();																										//backup
	resetEncoders();
	setMotors(100,-100,0);																			//rotate 180
	while(getMotorEncoder(leftMotor) < 1350) {}
	setMotors(0,0,0);
	playSound(5);

	//3. 3 phases
	bool shouldRetract = false;
	while(true) {
		if (edgeFoundRGB()) {																			//c. detect edge, backup, scan. *note it has priority
			backup();
			playSound(3);
			shouldRetract=false;
			scanTilt();
		}
		else if (robotFound()) {																	//b. detect robot. ram into it
			setMotors(80,80,100);
			playSound(2);
			shouldRetract = true;
		}
		else {																										//a. go straight (default state)
			retract(shouldRetract);
			shouldRetract=false;
			setMotors(80,80,0);
		}
	}
}
